+        current_paths: [{ id: 1, slug: "bp", title: "Fondamentaux", completion_percent: 40 }],
+        next_lesson: { id: 7, title: "Les variables" },
+        skills: [{ id: 1, name: "Variables", mastery_score: 60, is_mastered: false }],
